  ('fracas', '/frəˈkɑː/', '喧闹；骚乱', 'A noisy argument or disagreement, often involving violence.'),
  ('feckless', '/ˈfɛk.ləs/', '无能的；无效的', 'Lacking initiative or strength of character; ineffective.'),
  ('fissile', '/ˈfɪs.aɪl/', '可裂变的', 'Capable of undergoing nuclear fission to release energy.'),
  ('actuarial', '/ˌæktʃuˈɛr.i.əl/', '精算的', 'Relating to assessing risk, especially in insurance and finance.'),
  ('chaff', '/ʧæf/', '谷物脱壳后的残渣；无价值的东西', 'The worthless part of something, often discarded or separated.'),
  ('curdle', '/ˈkɜr.dəl/', '凝固；变稠', 'To thicken or form into clots, usually of liquid.'),
  ('lumen', '/ˈluː.mən/', '光通量，光照度', 'A measure of the amount of light emitted.'),
  ('hoary', '/ˈhɔːr.i/', '苍白的；古老的', 'Gray or white with age; very old or ancient.'),
  ('impregnable', '/ɪmˈprɛɡ.nə.bəl/', '坚不可摧的', 'Unable to be captured or broken into.'),
  ('ostracism', '/ˈɒs.trə.sɪ.zəm/', '排斥；孤立', 'Exclusion from a group or society by general consensus.'),
  ('blithe', '/blaɪð/', '快乐的；无忧无虑的', 'Free-spirited and carefree; cheerful and lighthearted.'),
  ('reaper', '/ˈriː.pər/', '收割者', 'A person or device that cuts and gathers crops.'),
  ('idyll', '/ˈaɪ.dəl/', '田园诗；田园生活', 'A peaceful or picturesque scene, often in nature.'),
  ('typo', '/ˈtaɪ.poʊ/', '打印错误', 'A mistake made in printed or written text.'),
  ('anagram', '/ˈæn.ə.ɡræm/', '变换字母组成的新词', 'A word formed by rearranging the letters of another.'),
  ('inchoate', '/ɪnˈkoʊ.ɪt/', '初步的；未成熟的', 'Not yet fully formed or developed; rudimentary.'),
  ('lumberjack', '/ˈlʌm.bər.dʒæk/', '伐木工', 'A person who cuts down trees for timber or firewood.'),
  ('deflated', '/dɪˈfleɪtɪd/', '瘪的；泄气的', 'Reduced in size or force; lacking in energy or enthusiasm.'),
  ('littoral', '/ˈlɪt.ər.əl/', '沿海的；海岸的', 'Relating to or situated on the shore of a sea or lake.'),
  ('aorta', '/eɪˈɔːr.tə/', '主动脉', 'The main artery that carries blood from the heart.'),
  ('dereliction', '/ˌdɛrəˈlɪkʃən/', '失职；玩忽职守', 'The failure to fulfill a duty or responsibility.'),
  ('flustered', '/ˈflʌs.tərd/', '慌乱的', 'In a state of nervous confusion or agitation.'),
  ('refractory', '/rɪˈfræk.tər.i/', '难驾驭的；倔强的', 'Difficult to manage or control; resistant to treatment or influence.'),
  ('podiatrist', '/pəˈdaɪ.ə.trɪst/', '足病医生', 'A medical specialist treating foot and ankle disorders.'),
  ('gangrene', '/ˈɡæŋ.ɡriːn/', '坏疽', 'Death of body tissue due to lack of blood flow or infection.'),
  ('yeoman', '/ˈjoʊ.mən/', '农夫；自由民', 'A commoner holding land under a feudal system.'),
