  ('harpsichord', '/ˈhɑːr.p.sɪ.kɔːrd/', '羽管键琴', 'A musical instrument with strings plucked by quills.'),
  ('bedlam', '/ˈbɛd.ləm/', '混乱；喧闹', 'A scene of uproar and confusion; chaos.'),
  ('albino', '/ælˈbaɪ.noʊ/', '白化病患者', 'A person or animal lacking pigmentation in their skin or hair.'),
  ('fracas', '/frəˈkɑː/', '喧闹；骚乱', 'A noisy argument or disagreement, often involving violence.'),
