  ('hoary', '/ˈhɔːr.i/', '苍白的；古老的', 'Gray or white with age; very old or ancient.'),
  ('impregnable', '/ɪmˈprɛɡ.nə.bəl/', '坚不可摧的', 'Unable to be captured or broken into.'),
